class Solution {
    public int maxScore(int[] nums){
        Arrays.sort(nums);
        long sum=0;
        int answer=0;
        for(int i=nums.length-1;i>=0;i--){
            sum+=nums[i];
            if(sum<=0)break;
            answer++;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maxScore(nums:IntArray):Int{
        nums.sort();
        var sum=0L;
        var answer=0;
        for(i in nums.indices.reversed()){
            sum+=nums[i];
            if(sum<=0)break;
            answer++
        };
        return answer
    }
}

